        // about 72 by arithmetic). The country filter already bounds the rows; this only refuses absurd areas.
        else if (c - a > 90 || d - b > 90) details.push({ field: 'bbox', issue: 'too_large', max_degrees: 90 });
        else bbox = [a, b, c, d];
      }
    }
