  url: `${String(cfg['ollama.base_url'] || '').replace(/\/+$/, '')}/api/embed`,
  body: { model: cfg['ollama.embed_model'] || 'bge-m3', input: [q], truncate: true, keep_alive: cfg['llm.keep_alive'] || '10m' } } }];

// wf.api.search_v2 > "No jurisdiction": use_profile=true but neither the request nor a profile names one.
const v = $('Validate query').first().json;
return [{ json: { ok: false, gw: v.gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'Query parameters are invalid',
  details: [{ field: 'jurisdiction', issue: 'required' }] } } }];

